import{_ as r,C as i,o as t,c as n,a4 as l,b as h,w as e,a as s,E as u,a5 as d}from"./chunks/framework.9tZL7ZIQ.js";const g=JSON.parse('{"title":"所罗门兄弟危机 Salomon Crisis","description":"1991年巴菲特临危受命，担任所罗门兄弟临时董事长10个月，正直与勇气是最好的投资","frontmatter":{"title":"所罗门兄弟危机 Salomon Crisis","description":"1991年巴菲特临危受命，担任所罗门兄弟临时董事长10个月，正直与勇气是最好的投资"},"headers":[],"relativePath":"02_concepts/salomon-crisis.md","filePath":"02_concepts/salomon-crisis.md"}'),c={name:"02_concepts/salomon-crisis.md"};function q(p,a,b,_,m,f){const o=i("Mermaid");return t(),n("div",null,[a[1]||(a[1]=l('<h1 id="所罗门兄弟危机-salomon-crisis" tabindex="-1">所罗门兄弟危机 Salomon Crisis <a class="header-anchor" href="#所罗门兄弟危机-salomon-crisis" aria-label="Permalink to &quot;所罗门兄弟危机 Salomon Crisis&quot;">​</a></h1><blockquote><p>1991年，伯克希尔投资7亿美元的所罗门兄弟濒临崩溃。巴菲特临危受命，担任临时董事长。这是他投资生涯中最不寻常的10个月，也是理解&quot;正直与声誉&quot;价值的最佳案例。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1991年/核心总结">核心总结</a></strong></td><td style="text-align:left;">危机全程与处理方式</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1992年/核心总结">核心总结</a></strong></td><td style="text-align:left;">危机解除，所罗门重建</td></tr></tbody></table><hr><h2 id="一、危机的本质" tabindex="-1">一、危机的本质 <a class="header-anchor" href="#一、危机的本质" aria-label="Permalink to &quot;一、危机的本质&quot;">​</a></h2><p>所罗门兄弟（Salomon Inc.）是美国最大的投资银行之一，1991年陷入了严重的法律和信任危机：</p><p><strong>核心问题</strong>：所罗门兄弟的交易员（莫泽尔）长期操纵美国国债拍卖，违反了联邦法律。这不仅是犯罪行为，更威胁到公司的生存执照。</p><p>巴菲特的判断：</p><blockquote><p>&quot;所罗门的危机不是财务危机，而是正直危机。&quot;</p></blockquote><hr><h2 id="二、为什么巴菲特选择介入" tabindex="-1">二、为什么巴菲特选择介入 <a class="header-anchor" href="#二、为什么巴菲特选择介入" aria-label="Permalink to &quot;二、为什么巴菲特选择介入&quot;">​</a></h2><p>巴菲特在1991年信中解释了为什么他愿意出面：</p><blockquote><p>&quot;所罗门有12,000名员工，他们不应该因为少数人的错误而失去生计。更重要的是，所罗门的客户和债券持有人有权期待这家公司继续运营下去。&quot;</p></blockquote><p>他接任临时董事长时，明确了三个条件：</p><ol><li>全面披露所有问题，不隐瞒</li><li>修复合规体系，确保不再发生</li><li>重建正直文化</li></ol><hr><h2 id="三、核心原则-正直、勇气是救公司最重要的东西" tabindex="-1">三、核心原则：&quot;正直、勇气是救公司最重要的东西&quot; <a class="header-anchor" href="#三、核心原则-正直、勇气是救公司最重要的东西" aria-label="Permalink to &quot;三、核心原则：&quot;正直、勇气是救公司最重要的东西&quot;&quot;">​</a></h2><p>巴菲特在1991年信中写道：</p><blockquote><p>&quot;正直、勇气是救公司最重要的东西。&quot;</p></blockquote><p>这句话后来成为伯克希尔文化的核心原则。</p><p>他进一步解释：</p><ul><li>正直意味着完全透明，不欺骗任何人（客户、监管机构、股东）</li><li>勇气意味着面对问题不退缩，不为了短期利益掩盖长期风险</li><li>两者缺一不可：没有正直的勇气是鲁莽，没有勇气的正直是无能</li></ul><hr><h2 id="四、危机处理的方法论" tabindex="-1">四、危机处理的方法论 <a class="header-anchor" href="#四、危机处理的方法论" aria-label="Permalink to &quot;四、危机处理的方法论&quot;">​</a></h2><p>巴菲特处理所罗门危机的方式，是他管理哲学的集中体现：</p><p><strong>第一步：完全透明</strong></p><ul><li>主动向美联储和财政部披露所有问题</li><li>不试图掩盖或最小化</li><li>&quot;好消息可以等，坏消息必须立刻说&quot;</li></ul><p><strong>第二步：修复问题根源</strong></p><ul><li>不是简单地炒掉肇事者，而是重建整个合规体系</li><li>认识到这是系统性问题，而非个人问题</li></ul><p><strong>第三步：保护无辜者</strong></p><ul><li>12,000名员工中绝大多数是无辜的</li><li>他们的生计和声誉不应被少数人的错误毁掉</li></ul><hr><h2 id="五、1992年的最终结果" tabindex="-1">五、1992年的最终结果 <a class="header-anchor" href="#五、1992年的最终结果" aria-label="Permalink to &quot;五、1992年的最终结果&quot;">​</a></h2><p>1992年，所罗门危机正式解除。巴菲特写道：</p><blockquote><p>&quot;1992年，我们的所罗门优先股已经被回购。加上我们出售的股份，总共收回了约1.18亿美元，我们的投资成本约为7,000万美元。&quot;</p></blockquote><p>更重要的是，所罗门的声誉得到了恢复：</p><blockquote><p>&quot;在公司声誉改善程度排名中（311家公司），所罗门排名第二。&quot;</p></blockquote><hr><h2 id="六、对投资哲学的影响" tabindex="-1">六、对投资哲学的影响 <a class="header-anchor" href="#六、对投资哲学的影响" aria-label="Permalink to &quot;六、对投资哲学的影响&quot;">​</a></h2><p>所罗门危机强化了巴菲特对&quot;声誉&quot;价值的看法：</p><ol><li><strong>声誉是商业的命脉</strong>：一次丑闻可以摧毁数十年建立的信任</li><li><strong>正直是最好的保险</strong>：预防问题比处理问题更便宜</li><li><strong>短期利益永远不值得牺牲长期声誉</strong>：所罗门的交易员为了短期奖金，毁掉了公司和自己</li><li><strong>正直+勇气 = 可信赖</strong>：只有正直没有勇气是软弱的，只有勇气没有正直是危险的</li></ol><hr><h2 id="七、十年演进与长期影响" tabindex="-1">七、十年演进与长期影响 <a class="header-anchor" href="#七、十年演进与长期影响" aria-label="Permalink to &quot;七、十年演进与长期影响&quot;">​</a></h2><h3 id="_1980年代-投资布局" tabindex="-1">1980年代：投资布局 <a class="header-anchor" href="#_1980年代-投资布局" aria-label="Permalink to &quot;1980年代：投资布局&quot;">​</a></h3><ul><li>1987年，伯克希尔投资7亿美元购买所罗门兄弟可转换优先股</li><li>年股息9%，期待分享华尔街繁荣</li></ul><h3 id="_1991年-危机爆发" tabindex="-1">1991年：危机爆发 <a class="header-anchor" href="#_1991年-危机爆发" aria-label="Permalink to &quot;1991年：危机爆发&quot;">​</a></h3><ul><li>国债拍卖操纵案曝光，所罗门面临破产清算风险</li><li>巴菲特临危受命，担任临时董事长10个月</li><li>核心原则确立：&quot;正直、勇气是救公司最重要的东西&quot;</li></ul><h3 id="_1992年-危机解除" tabindex="-1">1992年：危机解除 <a class="header-anchor" href="#_1992年-危机解除" aria-label="Permalink to &quot;1992年：危机解除&quot;">​</a></h3><ul><li>所罗门声誉恢复，在311家公司中排名第二</li><li>伯克希尔收回约1.18亿美元，投资成本约7,000万美元</li><li>德里克·莫恩、鲍勃·德纳姆等关键人物得到认可</li></ul><h3 id="_1990年代后期至2000年代-文化传承" tabindex="-1">1990年代后期至2000年代：文化传承 <a class="header-anchor" href="#_1990年代后期至2000年代-文化传承" aria-label="Permalink to &quot;1990年代后期至2000年代：文化传承&quot;">​</a></h3><ul><li>所罗门的教训被写入伯克希尔的企业文化</li><li>&quot;在招聘时，我们看重三种品质：正直、聪明、活力。如果他们没有第一种，后两种会毁了你。&quot;成为经典语录</li></ul><h3 id="_2010年代以后-持续影响" tabindex="-1">2010年代以后：持续影响 <a class="header-anchor" href="#_2010年代以后-持续影响" aria-label="Permalink to &quot;2010年代以后：持续影响&quot;">​</a></h3><ul><li>2015年致股东信中，巴菲特再次强调：</li></ul><blockquote><p>&quot;建立声誉需要20年，毁掉它只需要5分钟。&quot;</p></blockquote><ul><li>所罗门危机成为商学院和企业培训的经典案例</li></ul><hr><h2 id="八、关键人物" tabindex="-1">八、关键人物 <a class="header-anchor" href="#八、关键人物" aria-label="Permalink to &quot;八、关键人物&quot;">​</a></h2><p>巴菲特在1992年信中特别感谢了以下人员：</p><ul><li><strong>德里克·莫恩（Deryck Maughan）</strong>：危机期间承担重任</li><li><strong>鲍勃·德纳姆（Bob Denham）</strong>：法律与合规重建</li><li><strong>唐·霍华德（Don Howard）</strong>：运营稳定</li><li><strong>约翰·麦克法兰（John Macfarlane）</strong>：财务安排</li><li><strong>罗恩·奥尔森（Ron Olson）</strong>：法律顾问</li></ul><p>这些人成为巴菲特日后&quot;信任清单&quot;的典范——正直、能力、危机中的稳定性。</p><hr><h2 id="九、教训总结" tabindex="-1">九、教训总结 <a class="header-anchor" href="#九、教训总结" aria-label="Permalink to &quot;九、教训总结&quot;">​</a></h2><h3 id="_1-声誉的价值" tabindex="-1">1. 声誉的价值 <a class="header-anchor" href="#_1-声誉的价值" aria-label="Permalink to &quot;1. 声誉的价值&quot;">​</a></h3><blockquote><p>&quot;建立声誉需要20年，毁掉它只需要5分钟。&quot;</p></blockquote><p>所罗门兄弟用数十年建立的市场地位，因少数人的不诚实行为差点毁于一旦。</p><h3 id="_2-正直是不可谈判的" tabindex="-1">2. 正直是不可谈判的 <a class="header-anchor" href="#_2-正直是不可谈判的" aria-label="Permalink to &quot;2. 正直是不可谈判的&quot;">​</a></h3><p>巴菲特在招聘时的经典标准：</p><blockquote><p>&quot;我们看重三种品质：正直、聪明、活力。如果他们没有第一种，后两种会毁了你。&quot;</p></blockquote><h3 id="_3-危机中的透明度" tabindex="-1">3. 危机中的透明度 <a class="header-anchor" href="#_3-危机中的透明度" aria-label="Permalink to &quot;3. 危机中的透明度&quot;">​</a></h3><p>&quot;好消息可以等，坏消息必须立刻说&quot;——这是巴菲特从所罗门危机中总结的核心管理原则。</p><h3 id="_4-保护无辜者" tabindex="-1">4. 保护无辜者 <a class="header-anchor" href="#_4-保护无辜者" aria-label="Permalink to &quot;4. 保护无辜者&quot;">​</a></h3><p>12,000名员工的生计不应因少数人的错误而毁灭——这是巴菲特的道德担当。</p><h3 id="_5-长期视角" tabindex="-1">5. 长期视角 <a class="header-anchor" href="#_5-长期视角" aria-label="Permalink to &quot;5. 长期视角&quot;">​</a></h3><p>短期收益（如莫泽尔的交易利润）永远不值得牺牲长期声誉和可持续性。</p><hr><h2 id="主题关联" tabindex="-1">主题关联 <a class="header-anchor" href="#主题关联" aria-label="Permalink to &quot;主题关联&quot;">​</a></h2>',78)),(t(),h(d,null,{default:e(()=>[u(o,{id:"mermaid-414",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%E6%89%80%E7%BD%97%E9%97%A8%E5%8D%B1%E6%9C%BA%5D%20--%3E%20B%5B%E5%A3%B0%E8%AA%89%E7%AE%A1%E7%90%86%5D%0A%20%20%20%20A%20--%3E%20C%5B%E7%AE%A1%E7%90%86%E5%B1%82%E9%80%89%E6%8B%A9%5D%0A%20%20%20%20A%20--%3E%20D%5B%E9%A3%8E%E9%99%A9%E7%AE%A1%E7%90%86%5D%0A%20%20%20%20A%20--%3E%20E%5B%E4%BC%81%E4%B8%9A%E6%96%87%E5%8C%96%5D%0A%20%20%20%20A%20--%3E%20F%5B%E6%AD%A3%E7%9B%B4%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<hr><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/02_concepts/reputation">声誉</a> — 建立需20年，毁掉只需5分钟</li><li><a href="/02_concepts/management">管理层选择</a> — 正直的管理层是优质企业的标配</li><li><a href="/02_concepts/risk">风险</a> — 声誉风险的代价往往是致命的</li><li><a href="/search?q=企业文化">企业文化</a> — 正直、勇气与长期主义</li></ul><hr><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=核心总结">1991年：核心总结</a> → <a href="/01_letters/1991年/翻译">/01_letters/1991年/翻译</a></li><li><a href="/search?q=核心总结">1992年：核心总结</a> → <a href="/01_letters/1992年/翻译">/01_letters/1992年/翻译</a></li></ul><hr><p><em>本页面整理自<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>致股东信原文（1987-2025年），慢慢变富的卡尔编辑整理</em></p>',9))])}const E=r(c,[["render",q]]);export{g as __pageData,E as default};
